//! 🧪️ Native array index witnesses retain the exact original element and Source.
use semio_framework_value_retained_clone::*;
use semio_framework_value_clone_source_testing::{FixtureSourceBirth,FixtureCloseStep};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::mem::ManuallyDrop;
type Root=[u64;2];
struct Context<'a>{source:RetainedCloneRef<'a,Root>,turn:OriginalSourceTurnIdentity}
struct Close{owner:ManuallyDrop<RetainedOwnedProjectionAdmission<u64>>,source:(u64,usize,usize,usize),turn:OriginalSourceTurnIdentity}
impl Close{fn empty(&self)->bool{self.owner.terminal_is_empty()}}
impl Drop for Close{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.empty());unsafe{ManuallyDrop::drop(&mut self.owner)}}}
impl OriginalEffectProducer for Close{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source||c.turn!=self.turn{return Err(ValueError::invariant("field witness changed original Source"))}Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.owner.close_into(e,r)}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.owner.recover_close_into(e,r)}}
fn grant_for(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn paid_native_index_witness_retains_the_actual_element(){let law:serde_json::Value=serde_json::from_str(include_str!("native-index.json")).unwrap();let root=[law["left"].as_u64().unwrap(),law["right"].as_u64().unwrap()];let mut source=RetainedCloneSource::<Root>::from_owner(root);let id=source.borrow().reference_identity();let pointer=&source.borrow().get()[1] as *const u64;assert!(RetainedNativeArrayIndexProjection::<u64,2>::new(2).is_err());let witness=RetainedNativeArrayIndexProjection::<u64,2>::new(1).unwrap();let mut admission=ManuallyDrop::new(Some(RetainedOwnedProjectionAdmission::<u64>::default()));source.with_bank(|original,bank|{let owner=admission.as_mut().unwrap();let d=witness.demand(original,owner).unwrap();let work=witness.work_demand(original,owner).unwrap();let grant=grant_for(d);let denied=RetainedCloneGrant{maximum_items:0,..grant};for issued in [denied,grant]{let before=bank.wallet().remaining_work();let mut reply=None;let((poll,actual),heap)=observe(||bank.run_with_source(issued,work,|effect,_|{let start=effect.performed_work();drop(witness.admit_into(original,owner,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-start})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert!(actual.is_none());let step=reply.take().unwrap().unwrap();assert_eq!(heap,(0,0));if issued.maximum_items==0{assert_eq!(step.progress(),Default::default());assert_eq!(bank.wallet().remaining_work(),before);assert!(owner.terminal_is_empty())}else{assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(before-bank.wallet().remaining_work(),work);assert_eq!(owner.borrow().unwrap().get() as *const u64,pointer);assert_eq!(*owner.borrow().unwrap().get(),law["selected"].as_u64().unwrap())}assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),issued,heap)}}).unwrap();let mut authority=None;source.with_bank(|_,bank|{let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<RetainedOwnedProjectionAdmission<u64>>>()+std::mem::size_of::<Option<OriginalEffectAuthority<Close>>>(),depth:1,..Default::default()};let grant=grant_for(d);let((poll,_),heap)=observe(||bank.run_with_source(grant,1,|effect,witness|{let before=effect.performed_work();assert!(effect.performed(1).unwrap());authority=Some(OriginalEffectAuthority::new(Close{owner:ManuallyDrop::new(admission.take().unwrap()),source:id,turn:witness.identity()}));RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(done)=poll else{panic!("witness producer admission pending")};let step=done.result.unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap)}).unwrap();let mut action=None;let mut answer=None;for _ in 0..4096{let p=authority.as_ref().unwrap();if p.inspect(Close::empty){break}let(d,work)=p.inspect(|p|{assert!(!p.owner.requires_original_birth());assert!(!p.owner.requires_original_control());(p.owner.close_demand(4096).unwrap(),p.owner.close_work_demand(4096).unwrap())});let grant=grant_for(d);let mut physical=(0usize,0usize);loop{let((poll,actual),heap)=source.with_bank(|original,bank|{let observed=observe(||bank.run_with_source(grant,work,|effect,witness|{let start=effect.performed_work();let mut context=Context{source:original,turn:witness.identity()};let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-start;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));physical.0+=observed.1.0;physical.1+=observed.1.1;if let Some(actual)=observed.0.1{assert_eq!(actual,physical.0)}if let(RetainedWorkPoll::Complete(_),_)=&observed.0{assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.as_ref().unwrap().as_ref().unwrap();assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,physical)}observed}).unwrap();let _=(actual,heap);if let RetainedWorkPoll::Complete(done)=poll{done.result.unwrap();answer.take().unwrap().unwrap();break}}}assert!(authority.as_ref().unwrap().inspect(Close::empty));source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<Close>::producer_transfer_demand().unwrap();let grant=grant_for(d);let mut producer=None;let((poll,_),heap)=observe(||bank.run_with_source(grant,1,|effect,witness|{let context=Context{source:original,turn:witness.identity()};RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&context,&mut producer,effect))}));let RetainedWorkPoll::Complete(done)=poll else{panic!("field witness producer transfer pending")};let progress=done.result.unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);let release=unsafe{RetainedCursorRelease::native(Close::empty)};let d=release.inline_demand();let grant=grant_for(d);let mut reply=None;let((poll,_),heap)=observe(||bank.run(grant,1,|effect|{let before=effect.performed_work();drop(release.inline_into(&mut producer,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));let step=reply.take().unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap)}).unwrap();for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("source close refused"),_=>{}}}assert!(source.terminal_is_empty());unsafe{ManuallyDrop::drop(&mut admission)}}
